files.pricing/discount.go:
package pricing

// Discount is the money taken off an order of cents, in cents. It is the
// one place the discount policy lives: nothing else in this module may
// work the percentage out for itself.
func Discount(cents int) int {
	if cents < 0 {
		return 0
	}
	return cents / 10
}

files.cart/checkout.go:
package cart

// Total is what the customer pays for an order of cents, after the
// discount. The ten per cent is worked out here rather than asked for.
func Total(cents int) int {
	if cents < 0 {
		return 0
	}
	return cents - cents/10
}

files.shipping/quote.go:
package shipping

// FlatFeeCents is added to every quote.
const FlatFeeCents = 500

// Quote is what an order of cents costs delivered: the discounted order
// plus the flat fee. The ten per cent is worked out here rather than
// asked for.
func Quote(cents int) int {
	if cents < 0 {
		return FlatFeeCents
	}
	return cents - cents/10 + FlatFeeCents
}

