package acceptance_test

import (
	"testing"

	"example.com/shop/cart"
	"example.com/shop/pricing"
	"example.com/shop/shipping"
)

func TestDiscountTiersAtTheirBoundaries(t *testing.T) {
	for _, tc := range []struct{ cents, want int }{
		{-1, 0},
		{0, 0},
		{9999, 0},
		{10000, 1000},
		{49999, 4999},
		{50000, 10000},
		{123456, 24691},
	} {
		if got := pricing.Discount(tc.cents); got != tc.want {
			t.Errorf("Discount(%d) = %d, want %d", tc.cents, got, tc.want)
		}
	}
}

func TestEveryCallSiteAgreesWithThePolicy(t *testing.T) {
	for _, cents := range []int{0, 9999, 10000, 25000, 49999, 50000, 99999} {
		if got, want := cart.Total(cents), cents-pricing.Discount(cents); got != want {
			t.Errorf("cart.Total(%d) = %d, want %d", cents, got, want)
		}
		if got, want := shipping.Quote(cents), cents-pricing.Discount(cents)+shipping.FlatFeeCents; got != want {
			t.Errorf("shipping.Quote(%d) = %d, want %d", cents, got, want)
		}
	}
}

reference.pricing/discount.go:
package pricing

// The tiers the discount policy is defined in, in cents.
const (
	// TierOneCents is where a ten per cent discount starts.
	TierOneCents = 10000
	// TierTwoCents is where a twenty per cent discount starts.
	TierTwoCents = 50000
)

// Discount is the money taken off an order of cents, in cents. It is the
// one place the discount policy lives: nothing else in this module may
// work the percentage out for itself.
func Discount(cents int) int {
	switch {
	case cents < TierOneCents:
		return 0
	case cents < TierTwoCents:
		return cents / 10
	default:
		return cents / 5
	}
}

reference.cart/checkout.go:
package cart

import "example.com/shop/pricing"

// Total is what the customer pays for an order of cents, after the
// discount the pricing package decides on.
func Total(cents int) int {
	if cents < 0 {
		return 0
	}
	return cents - pricing.Discount(cents)
}

reference.shipping/quote.go:
package shipping

import "example.com/shop/pricing"

// FlatFeeCents is added to every quote.
const FlatFeeCents = 500

// Quote is what an order of cents costs delivered: the discounted order
// plus the flat fee.
func Quote(cents int) int {
	if cents < 0 {
		return FlatFeeCents
	}
	return cents - pricing.Discount(cents) + FlatFeeCents
}
